export const POOL=['Na','Cl','Fe','O','C','H','Au','Li','He','Be','B','N','F','Ne','Mg','Al','Si','P','S'];
export const clone=x=>x.map(t=>[...t]);
export const solved=t=>t.every(a=>!a.length||(a.length===4&&a.every(v=>v===a[0])));
export function move(t,a,b){if(a===b||!t[a]?.length||!t[b]||t[b].length===4)return null;const x=t[a].at(-1);if(t[b].length&&t[b].at(-1)!==x)return null;let n=0;for(let i=t[a].length-1;i>=0&&t[a][i]===x;i--)n++;n=Math.min(n,4-t[b].length);const out=clone(t);out[b].push(...out[a].splice(-n));return out;}
const key=t=>t.map(a=>a.join(',')).join('|');
function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export function createCertifiedPuzzle(symbols,level,seed,recent=[]){for(let attempt=0;attempt<30;attempt++){const r=rng(seed+attempt*7919);let t=symbols.map(s=>[s,s,s,s]);t.push([],[]);let solution=[];let seen=new Set([key(t)]);for(let step=0;step<18+symbols.length*7;step++){const candidates=[];for(let a=0;a<t.length;a++)for(let b=0;b<t.length;b++){if(a===b||!t[a].length||t[b].length===4)continue;let x=t[a].at(-1),run=0;for(let i=t[a].length-1;i>=0&&t[a][i]===x;i--)run++;for(let n=1;n<=Math.min(run,4-t[b].length);n++){const next=clone(t);next[b].push(...next[a].splice(-n));const back=move(next,b,a);if(back&&key(back)===key(t)&&!seen.has(key(next)))candidates.push({next,rev:[b,a]});}}if(!candidates.length)break;const c=candidates[Math.floor(r()*candidates.length)];t=c.next;solution.unshift(c.rev);seen.add(key(t));}if(solved(t))continue;const puzzleKey=key(t);if(recent.includes(puzzleKey)&&attempt<29)continue;let check=clone(t);for(const [a,b]of solution){check=move(check,a,b);if(!check)throw Error('Invalid certificate');}if(!solved(check))throw Error('Unsolved certificate');return{tubes:t,solution,key:puzzleKey,seed,level};}throw Error('No certified puzzle');}
export const symbolCount=l=>l<4?3:l<8?4:l<15?5:6;
export const budget=(p,l)=>Math.max(9,p.solution.length+(l<5?6:l<10?4:3));
export const defaults=()=>({level:1,gold:0,nug:0,xp:0,score:0,discovered:POOL.slice(0,3),streak:0,bestStreak:0,recentPuzzles:[]});
export function normalize(raw){const d=defaults();if(!raw||typeof raw!=='object')return d;for(const k of ['level','gold','nug','xp','score','streak','bestStreak'])if(Number.isFinite(raw[k]))d[k]=Math.max(k==='level'?1:0,Math.floor(raw[k]));d.discovered=[...new Set([...d.discovered,...(Array.isArray(raw.discovered)?raw.discovered.filter(s=>POOL.includes(s)):[])])];d.recentPuzzles=Array.isArray(raw.recentPuzzles)?raw.recentPuzzles.filter(s=>typeof s==='string').slice(-3):[];return d;}
